def build_question(item: tuple[str, ...], number: int, bank_offset: int) -> dict:
    concept_id, bloom, stem, stem_ar, options_en, options_ar, explanation, explanation_ar = item
    if len(options_en) != 4 or len(options_ar) != 4:
        raise ValueError(f"{concept_id}: each language needs four options")
    if len(set(options_en)) != 4 or len(set(options_ar)) != 4:
        raise ValueError(f"{concept_id}: duplicate option text")

    correct_index = (number - 1 + bank_offset) % 4

    def rotate(options: list[str]) -> list[str]:
        if correct_index == 0:
            return list(options)
        return list(options[-correct_index:]) + list(options[:-correct_index])

    en = rotate(options_en)
    ar = rotate(options_ar)
    return {
        "id": f"q{number}",
        "concept_id": concept_id,
        "bloom_level": bloom,
        "question": stem,
        "question_ar": stem_ar,
        "options": en.copy(),
        "options_en": en,
        "options_ar": ar,
        "answer": LETTERS[correct_index],
        "correct": correct_index,
        "explanation": explanation,
        "explanation_ar": explanation_ar,
    }


def main() -> None:
    template = json.loads(TEMPLATE.read_text(encoding="utf-8"))
    header = {key: value for key, value in template.items() if key != "questions"}
    for bank_offset, bank in enumerate(BANKS):
        output = dict(header)
        output.update({
            "quiz_id": bank["id"],
            "topic": bank["title"],
            "topic_ar": bank["title_ar"],
            "questions": [
                build_question(item, number, bank_offset)
                for number, item in enumerate(bank["items"], start=1)
            ],
        })
        path = BANK_DIR / f"{bank['id']}.json"
        path.write_text(json.dumps(output, ensure_ascii=False, indent=1) + "\n", encoding="utf-8")
        print(f"Built {path.name}")


if __name__ == "__main__":
    main()
